-- `create_index_names_first_in_enum_order_loud` with the enum part an expression,
-- `COALESCE(e, 'a')`, whose type is the enum.
-- @setup
CREATE TYPE e AS ENUM ('z', 'a');
CREATE TABLE t (e e, t text);
INSERT INTO t VALUES ('a', ''), ('z', '');
-- @test
-- @expect-error: the first oversized key in member order
-- @expect-message
-- @profile-lock
CREATE INDEX t_i ON t ((COALESCE(e, 'a')), t);
